export const getSearchUrl = (params: SearchParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/search?${stringifiedParams}` : `/api/v1/search`;
};

/**
 * @summary Сквозной поиск — номера, ИНН, название клиента, артикул; результаты группами по модулям
 */
export const search = async (
  params: SearchParams,
  options?: Parameters<typeof http>[1],
): Promise<SearchResult> => {
  return http<SearchResult>(getSearchUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getSearchQueryKey = (params?: SearchParams) => {
  return [`/api/v1/search`, ...(params ? [params] : [])] as const;
};

export const getSearchQueryOptions = <
  TData = Awaited<ReturnType<typeof search>>,
  TError = ErrorType<SessionExpiredResponse | ValidationFailedResponse>,
>(
  params: SearchParams,
  options?: {
    query?: Partial<UseQueryOptions<Awaited<ReturnType<typeof search>>, TError, TData>>;
    request?: SecondParameter<typeof http>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getSearchQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof search>>> = ({ signal }) =>
    search(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof search>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData, TError> };
};

